mapper.select:

/* Biz: gscm.r.pm.prdb.db.DPLA018.S902 사용자 권한 체크 */
SELECT USER_ID
	 , MENU_ID
	 , AUTH_TYP_CD
  FROM COM_USER_AUTH
 WHERE USER_ID = #{USER_ID}
   AND MENU_ID = #{MENU_ID}
   AND AUTH_TYP_CD IN ('R','W')


/* Biz: gscm.r.pm.prdb.db.DPLA018.S002 생산원가 상세 조회 */
SELECT B.TGT_CD
	 , B.DTL_SEQ
	 , B.REMARK_CD AS METRIC_VALUE
	 , B.METRIC_TYPE
  FROM PRO_DTL_08 B
 WHERE B.TGT_CD = #{TGT_CD}
   AND B.METRIC_TYPE = #{METRIC_TYPE}
